import spinal.core._
import spinal.core.sim._
import spinal.lib._
import java.io.{File, PrintWriter}
import scala.io.Source

/** Only the non-PW portion is nested; PwMac is compiled as a root because its existing
  * internal PwRequant uses parent-scope stream arbitration. */
class MkdcCascadeTop extends Component {
  val lb3 = new LineBuffer(LineBufferConfig(k = 3)); val lb5 = new LineBuffer(LineBufferConfig(k = 5))
  val dw3 = new Dw3x3(); val dw5 = new Dw5x5(); val merge = new ElementAdd(ElementAddConfig())
  val r3 = Reg(UInt(10 bits)) init(0); val c3 = Reg(UInt(10 bits)) init(0)
  val r5 = Reg(UInt(10 bits)) init(0); val c5 = Reg(UInt(10 bits)) init(0)
  val w3 = Stream(Dw3x3Window(Dw3x3Config())); val w5 = Stream(Dw5x5Window(Dw5x5Config()))
  w3.valid := lb3.io.output_o.valid; lb3.io.output_o.ready := w3.ready; w3.payload.window := lb3.io.output_o.fragment.window
  w3.payload.tag.group := lb3.io.output_o.fragment.group; w3.payload.tag.row := r3; w3.payload.tag.col := c3
  w3.payload.tag.group_last := lb3.io.output_o.fragment.group_last; w3.payload.tag.last := lb3.io.output_o.last; dw3.io.input_i << w3
  when(w3.fire){when(c3===3){c3:=0;when(r3===3){r3:=0} otherwise {r3:=r3+1}} otherwise {c3:=c3+1}}
  w5.valid := lb5.io.output_o.valid; lb5.io.output_o.ready := w5.ready; w5.payload.window := lb5.io.output_o.fragment.window
  w5.payload.tag.group := lb5.io.output_o.fragment.group; w5.payload.tag.row := r5; w5.payload.tag.col := c5
  w5.payload.tag.group_last := lb5.io.output_o.fragment.group_last; w5.payload.tag.last := lb5.io.output_o.last; dw5.io.input_i << w5
  when(w5.fire){when(c5===3){c5:=0;when(r5===3){r5:=0} otherwise {r5:=r5+1}} otherwise {c5:=c5+1}}
  merge.io.a_i.valid := dw3.io.output_o.valid; merge.io.b_i.valid := dw5.io.output_o.valid
  dw3.io.output_o.ready := merge.io.a_i.ready; dw5.io.output_o.ready := merge.io.b_i.ready
  for(l<-0 until 16){merge.io.a_i.payload(l*32,32 bits):=dw3.io.output_o.mac(l).asBits;merge.io.b_i.payload(l*32,32 bits):=dw5.io.output_o.mac(l).asBits}
  for(x<-Seq(lb3.io.cfg_i,lb3.io.input_i,lb3.io.output_o,lb5.io.cfg_i,lb5.io.input_i,lb5.io.output_o,
    dw3.io.cfg_i,dw3.io.weights_i,dw3.io.params_i,dw3.io.input_i,dw3.io.output_o,
    dw5.io.cfg_i,dw5.io.weights_i,dw5.io.params_i,dw5.io.input_i,dw5.io.output_o,
    merge.io.cfg_i,merge.io.a_i,merge.io.b_i,merge.io.output_o))x.simPublic()
}

object MkdcBlockSim extends App {
