  val vr=new File("../PW/verification/vectors");val d3=new File("../DW3x3/verification/vectors");val d5=new File("../DW5x5/verification/vectors");val mj=new File("../DW_Join/verification/vectors");val fv=new File("verification/vectors")
  def dir(n:String)=new File(vr,n)
