  val exStim=hex(new File(ex,"stimulus.hex"));val exQ=hex(new File(ex,"golden.hex"));val exW=hex(new File(ex,"weights.hex"));val exP=hex(new File(ex,"params.hex"))
  val prStim=hex(new File(pr,"stimulus.hex"));val prM=hex(new File(pr,"mac.hex"));val prW=hex(new File(pr,"weights.hex"));val prP=hex(new File(pr,"params.hex"))
  val skStim=hex(new File(sk,"stimulus.hex"));val skM=hex(new File(sk,"mac.hex"));val skW=hex(new File(sk,"weights.hex"));val skP=hex(new File(sk,"params.hex"))
  val d3W=hex(new File(d3,"weights.hex"));val d3P=hex(new File(d3,"params.hex"));val d3G=hex(new File(d3,"golden_mac.hex"));val d5W=hex(new File(d5,"weights.hex"));val d5P=hex(new File(d5,"params.hex"));val d5G=hex(new File(d5,"golden_mac.hex"))
  val mG=hex(new File(mj,"merge_golden.hex"));val mA=hex(new File(mj,"merge_params_a.hex"));val mB=hex(new File(mj,"merge_params_b.hex"));val mZ=hex(new File(mj,"merge_bias.hex"));val fG=hex(new File(fv,"final_golden.hex"));val fP=hex(new File(fv,"final_params.hex"))
  val groups=8;val pixels=16;val words=groups*pixels
  var cycle=0L;var expN=0;var projectN=0;var skipN=0;var d3N=0;var d5N=0;var mixN=0;var finalN=0;var stalls=0
  val log=new PrintWriter(new File(root,"run.log"));val csv=new PrintWriter(new File(root,"sim_trace.csv"));csv.println("cycle,stage,valid,ready,index")
  def fail(s:String):Nothing={log.println(s"FAIL cycle=$cycle $s");log.flush();simFailure(s)}
  def loadPw(dut:PwMac,cin:Int,cout:Int,stim:Vector[BigInt],w:Vector[BigInt],p:Vector[BigInt],raw:Boolean):Unit={
    dut.io.cfg_i.cin#=cin;dut.io.cfg_i.cout#=cout;dut.io.cfg_i.pixels#=pixels;dut.io.cfg_i.shift#=24;dut.io.cfg_i.raw#=raw;dut.io.cfg_i.int16#=false;dut.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();if(!dut.io.cfg_i.ready.toBoolean)fail("PW cfg rejected");dut.clockDomain.waitFallingEdge();dut.io.cfg_i.valid#=false
