    dut.io.start_i.payload#=true;dut.io.start_i.valid#=true;while(!dut.io.start_i.ready.toBoolean)dut.clockDomain.waitSampling();dut.clockDomain.waitSampling();dut.io.start_i.valid#=false
  }
  def runPw(name:String,cin:Int,cout:Int,stim:Vector[BigInt],w:Vector[BigInt],p:Vector[BigInt],raw:Boolean,exp:Vector[BigInt]):Vector[BigInt]={
    val out=scala.collection.mutable.ArrayBuffer[BigInt]();val comp=SimConfig.withConfig(SpinalConfig(defaultConfigForClockDomains=ClockDomainConfig(resetKind=ASYNC,resetActiveLevel=LOW))).withFstWave.workspacePath(new File(root,s"${name}_workspace").getPath).compile { val dut = new PwMac(); dut }
    comp.doSim(name,20261015){dut=>dut.clockDomain.forkStimulus(10);dut.io.rd_o.ready#=true;dut.io.rsp_i.valid#=false;dut.io.output_o.ready#=true;dut.clockDomain.waitSampling(3);loadPw(dut,cin,cout,stim,w,p,raw);var pending:Option[BigInt]=None;var done=false;var guard=0
