  val expandWords=(for(g<-0 until 8;p<-0 until 16)yield{(0 until 4).map{sub=>val b=expandBeats((g*4+sub)*16+p);(0 until 4).map(l=>((b>>(16*l))&255)<<(8*l)).foldLeft(BigInt(0))(_|_)<<(32*sub)}.foldLeft(BigInt(0))(_|_)}).toVector
  cycle=0
  val cascade=SimConfig.withConfig(SpinalConfig(defaultConfigForClockDomains=ClockDomainConfig(resetKind=ASYNC,resetActiveLevel=LOW))).withFstWave.workspacePath(new File(root,"cascade_workspace").getPath).compile(new LineDwCascadeTop)
  val mixWords=scala.collection.mutable.ArrayBuffer[BigInt]();cascade.doSim("cascade",20261015){dut=>dut.clockDomain.forkStimulus(10);dut.lb3.io.cfg_i.valid#=false;dut.lb5.io.cfg_i.valid#=false;dut.lb3.io.input_i.valid#=false;dut.lb5.io.input_i.valid#=false;dut.dw3.io.cfg_i.valid#=false;dut.dw3.io.weights_i.valid#=false;dut.dw3.io.params_i.valid#=false;dut.dw5.io.cfg_i.valid#=false;dut.dw5.io.weights_i.valid#=false;dut.dw5.io.params_i.valid#=false;dut.merge.io.cfg_i.valid#=false;dut.merge.io.output_o.ready#=false;dut.clockDomain.waitSampling(5);dut.lb3.io.cfg_i.width#=4;dut.lb3.io.cfg_i.height#=4;dut.lb3.io.cfg_i.groups#=groups;dut.lb3.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();if(!dut.lb3.io.cfg_i.ready.toBoolean)fail("LB3 config rejected");dut.clockDomain.waitFallingEdge();dut.lb3.io.cfg_i.valid#=false;dut.lb5.io.cfg_i.width#=4;dut.lb5.io.cfg_i.height#=4;dut.lb5.io.cfg_i.groups#=groups;dut.lb5.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();if(!dut.lb5.io.cfg_i.ready.toBoolean)fail("LB5 config rejected");dut.clockDomain.waitFallingEdge();dut.lb5.io.cfg_i.valid#=false
    def loadDw3():Unit={val c=dut.dw3;c.io.cfg_i.groups#=groups;c.io.cfg_i.raw#=true;c.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();c.io.cfg_i.valid#=false;dut.clockDomain.waitFallingEdge();for(i<-0 until groups){c.io.weights_i.payload#=d3W(i);c.io.params_i.payload#=d3P(i);c.io.weights_i.valid#=true;c.io.params_i.valid#=true;while(!(c.io.weights_i.ready.toBoolean&&c.io.params_i.ready.toBoolean))dut.clockDomain.waitSampling();dut.clockDomain.waitSampling();c.io.weights_i.valid#=false;c.io.params_i.valid#=false}}
    def loadDw5():Unit={val c=dut.dw5;c.io.cfg_i.groups#=groups;c.io.cfg_i.raw#=true;c.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();c.io.cfg_i.valid#=false;dut.clockDomain.waitFallingEdge();for(i<-0 until groups){c.io.weights_i.payload#=d5W(i);c.io.params_i.payload#=d5P(i);c.io.weights_i.valid#=true;c.io.params_i.valid#=true;while(!(c.io.weights_i.ready.toBoolean&&c.io.params_i.ready.toBoolean))dut.clockDomain.waitSampling();dut.clockDomain.waitSampling();c.io.weights_i.valid#=false;c.io.params_i.valid#=false}}
    loadDw3();loadDw5();var ag=0;def ca(g:Int):Unit={for(l<-0 until 16){dut.merge.io.cfg_i.multiplier_a(l)#=signed((mA(g)>>(22*l))&((BigInt(1)<<22)-1),22);dut.merge.io.cfg_i.multiplier_b(l)#=signed((mB(g)>>(22*l))&((BigInt(1)<<22)-1),22);dut.merge.io.cfg_i.bias_fixed(l)#=signed((mZ(g)>>(64*l))&((BigInt(1)<<64)-1),64)};dut.merge.io.cfg_i.words#=pixels;dut.merge.io.cfg_i.group#=g;dut.merge.io.cfg_i.last_group#=(g==groups-1);dut.merge.io.cfg_i.shift#=24;dut.merge.io.cfg_i.clamp_min#=0;dut.merge.io.cfg_i.clamp_max#=127;dut.merge.io.cfg_i.valid#=true;dut.clockDomain.waitSampling();if(!dut.merge.io.cfg_i.ready.toBoolean)fail(s"merge config $g rejected");dut.clockDomain.waitFallingEdge();dut.merge.io.cfg_i.valid#=false};ca(0)
    var sent3=0;var sent5=0;var lb3N=0;var lb5N=0;var guard=0;while(mixWords.size<words){dut.clockDomain.waitFallingEdge();val iv3=sent3<expandWords.size;val iv5=sent5<expandWords.size;dut.lb3.io.input_i.valid#=iv3;dut.lb5.io.input_i.valid#=iv5;dut.lb3.io.input_i.payload#=(if(iv3)expandWords(sent3)else BigInt(0));dut.lb5.io.input_i.payload#=(if(iv5)expandWords(sent5)else BigInt(0));dut.merge.io.output_o.ready#=(cycle%13!=6||mixWords.size==words-1);dut.clockDomain.waitSampling();cycle+=1;if(iv3 && dut.lb3.io.input_i.ready.toBoolean)sent3+=1;if(iv5 && dut.lb5.io.input_i.ready.toBoolean)sent5+=1;val lf3=dut.lb3.io.output_o.valid.toBoolean&&dut.lb3.io.output_o.ready.toBoolean;val lf5=dut.lb5.io.output_o.valid.toBoolean&&dut.lb5.io.output_o.ready.toBoolean;if(lf3){val q=lb3N%pixels;val g=lb3N/pixels;val rr=q/4;val cc=q%4;for(r<-0 until 3;c<-0 until 3){val er=rr+r-1;val ec=cc+c-1;val ex=if(er<0||er>=4||ec<0||ec>=4)BigInt(0)else expandWords(g*pixels+er*4+ec);if(dut.lb3.io.output_o.fragment.window(r)(c).toBigInt!=ex)fail(s"LB3 window mismatch $lb3N r=$r c=$c exp=0x${ex.toString(16)} got=0x${dut.lb3.io.output_o.fragment.window(r)(c).toBigInt.toString(16)}")};lb3N+=1};if(lf5){lb5N+=1};val f3=dut.dw3.io.output_o.valid.toBoolean&&dut.dw3.io.output_o.ready.toBoolean;val f5=dut.dw5.io.output_o.valid.toBoolean&&dut.dw5.io.output_o.ready.toBoolean;val fm=dut.merge.io.output_o.valid.toBoolean&&dut.merge.io.output_o.ready.toBoolean;if(f3){val got=(0 until 16).map(i=>(dut.dw3.io.output_o.mac(i).toBigInt&0xffffffffL)<<(32*i)).foldLeft(BigInt(0))(_|_);if(got!=d3G(d3N))fail(s"DW3 mismatch $d3N exp=0x${d3G(d3N).toString(16)} got=0x${got.toString(16)} g=${dut.dw3.io.output_o.tag.group.toBigInt} r=${dut.dw3.io.output_o.tag.row.toBigInt} c=${dut.dw3.io.output_o.tag.col.toBigInt}");d3N+=1};if(f5){val got=(0 until 16).map(i=>(dut.dw5.io.output_o.mac(i).toBigInt&0xffffffffL)<<(32*i)).foldLeft(BigInt(0))(_|_);if(got!=d5G(d5N))fail(s"DW5 mismatch $d5N exp=0x${d5G(d5N).toString(16)} got=0x${got.to