  val summary=s"[TB PASSED] mkdc mid expand=$expN dw3=${d3N*16} dw5=${d5N*16} mix=${mixWords.size*16} project=$projectN skip=$skipN final=${finalN*16} stalls=$stalls";println(summary);log.println(summary);log.flush();csv.close();new PrintWriter(new File(root,"result.json")){write(s"""{"status":"PASS","block":"vessel_mid","expand_values":$expN,"dw3_values":${d3N*16},"dw5_values":${d5N*16},"mix_values":${mixWords.size*16},"project_values":$projectN,"skip_values":$skipN,"final_values":${finalN*16},"shuffle":"identity_absorbed","stalls":$stalls}""");close()}
